  Prefs full=new Prefs();WorkspaceFavoritesStore all=store(full);for(int i=0;i<64;i++)all.pin(doc(i),"Same title",WorkspaceFavoritesStore.Kind.DOCUMENT);check(all.read().size()==64,"64 records");prior=full.raw;reject(()->all.pin(doc(64),"65th",WorkspaceFavoritesStore.Kind.DOCUMENT));check(full.raw.equals(prior),"no eviction");all.pin(doc(0),"updated",WorkspaceFavoritesStore.Kind.DOCUMENT);check(all.read().get(0).label.equals("updated"),"at capacity existing update");all.unpin(doc(0));all.pin(doc(64),"replacement",WorkspaceFavoritesStore.Kind.DOCUMENT);check(all.read().get(63).uri.toString().equals(doc(64).toString()),"explicit space and stable append");
  Prefs identity=new Prefs();WorkspaceFavoritesStore ids=store(identity);for(String u:new String[]{"content://p/document/a%2Fb","content://p/document/a%2fb","content://p/document/a/b","content://p/document/a%252Fb"})ids.pin(Uri.parse(u),"same",WorkspaceFavoritesStore.Kind.DOCUMENT);check(ids.read().size()==4,"exact URI spelling no alias");
  Prefs bounds=new Prefs();WorkspaceFavoritesStore b=store(bounds);String base="content://p/document/";Uri exact=Uri.parse(base+"x".repeat(4096-base.length()));b.pin(exact,"x".repeat(256),WorkspaceFavoritesStore.Kind.DOCUMENT);check(b.read().get(0).uri.toString().length()==4096&&b.read().get(0).label.length()==256,"exact fields");reject(()->b.pin(Uri.parse(exact.toString()+"x"),"x",WorkspaceFavoritesStore.Kind.DOCUMENT));reject(()->b.pin(doc(0),"x".repeat(257),WorkspaceFavoritesStore.Kind.DOCUMENT));
  reject(()->b.pin(doc(0),"",WorkspaceFavoritesStore.Kind.DOCUMENT));reject(()->b.pin(doc(0),"\ud800",WorkspaceFavoritesStore.Kind.DOCUMENT));reject(()->b.pin(Uri.parse(base+"\ud800"),"x",WorkspaceFavoritesStore.Kind.DOCUMENT));reject(()->b.pin(Uri.parse("file:///tmp/x"),"x",WorkspaceFavoritesStore.Kind.DOCUMENT));reject(()->b.pin(Uri.parse("content:///x"),"x",WorkspaceFavoritesStore.Kind.DOCUMENT));reject(()->b.pin(doc(0),"x",WorkspaceFavoritesStore.Kind.TREE));
  Prefs escaping=new Prefs();WorkspaceFavoritesStore escaped=store(escaping);escaped.pin(doc(0),"quotes \\\" braces []{} apostrophe ' \\ \n 😀",WorkspaceFavoritesStore.Kind.DOCUMENT);check(escaped.read().get(0).label.contains("😀"),"proper escaped Unicode and delimiters");
  String valid=envelope(row(doc(0).toString(),"x","DOCUMENT"));String[] corrupt={"{",valid+"x",valid.replace("\"version\":1","\"version\":2"),"{'version':1,'favorites':[]}","{version:1, favorites:[]}","{\"version\":1,/*x*/\"favorites\":[]}",valid.replace("\"version\":1","\"version\":1,\"\\u0076ersion\":1"),envelope(row(doc(0).toString(),"x","DOCUMENT")+","+row(doc(0).toString(),"x","TREE")),envelope(row(doc(0).toString(),"x","DOCUMENT")+","+row(doc(0).toString(),"different","DOCUMENT")),envelope(String.join(",",Collections.nCopies(65,row(doc(0).toString(),"x","DOCUMENT")))),valid.replace("DOCUMENT","document"),valid.replace("\"label\":\"x\"","\"label\":1"),valid.replace("\"label\":\"x\"","\"label\":\"x\",\"\\u006cabel\":\"x\""),valid.replace("\"label\":\"x\"","\"label\":\"\\uD800\""),valid.replace("\"kind\":\"DOCUMENT\"","\"kind\":\"DOCUMENT\",\"unknown\":1"),"[".repeat(12000)+"0"+"]".repeat(12000),"[".repeat(9)+"0"+"]".repeat(9),"x".repeat(32769)};
  for(String raw:corrupt){Prefs broken=new Prefs();broken.raw=raw;WorkspaceFavoritesStore x=store(broken);reject(x::read);reject(()->x.pin(doc(9),"new",WorkspaceFavoritesStore.Kind.DOCUMENT));reject(()->x.unpin(doc(9)));check(broken.raw.equals(raw)&&broken.commits==0,"corruption preserved all APIs");}
  Prefs serialized=new Prefs();String empty=envelope("");serialized.raw=empty+" ".repeat(32768-empty.length());check(store(serialized).read().isEmpty(),"exact32768 serialized");serialized.raw+=" ";reject(()->store(serialized).read());
  Prefs expansion=new Prefs();WorkspaceFavoritesStore e=store(expansion);boolean refused=false;for(int i=0;i<64;i++){String old=expansion.raw;try{e.pin(Uri.parse(base+i+"x".repeat(3900)),"\n".repeat(256),WorkspaceFavoritesStore.Kind.DOCUMENT);}catch(IOException expected){check(Objects.equals(old,expansion.raw),"write cap preserves prior data");refused=true;break;}}check(refused&&expansion.raw.length()<=32768,"escaped serialized cap before64 possible");
  Prefs failing=new Prefs();WorkspaceFavoritesStore fs=store(failing);failing.success=false;reject(()->fs.pin(doc(0),"memory changed",WorkspaceFavoritesStore.Kind.DOCUMENT));check(fs.read().get(0).label.equals("memory changed"),"commit false may change memory without durable success");failing.fail=true;reject(()->fs.unpin(doc(0)));
  failing.fail=false;failing.success=true;int repair=failing.commits;fs.unpin(doc(0));check(failing.commits==repair+1&&fs.read().isEmpty(),"retry absent unpin still commits after false/throw changed memory");
  Prefs shared=new Prefs();ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Future<?>> work=new ArrayList<>();for(int thread=0;thread<2;thread++){final int start=thread*16;work.add(pool.submit(()->{for(int i=start;i<start+16;i++)try{store(shared).pin(doc(i),"x",WorkspaceFavoritesStore.Kind.DOCUMENT);}catch(IOException failure){throw new RuntimeException(failure);}}));}for(Future<?> future:work)future.get(5,TimeUnit.SECONDS);check(store(shared).read().size()==32,"independent instances serialized no lost pins");}finally{pool.shutdownNow();}
  System.out.println("PASS workspace favorites: "+checks+" assertions");
